"""Minimal simulating maps of data generated by a monotone map.

Setting (Makdesi, Girard, Fribourg, "Data-driven models of monotone systems", IEEE TAC):
data (z_k, y_k), k in K, satisfy

    y_k in F(z_k) = f(z_k) + [d_lo, d_hi],

with f: R^n -> R^m monotone and unknown, and the disturbance bounds known. The
minimal simulating map is the interval-valued map

    S_m(z) = [ sup{ y_k - (d_hi - d_lo) : z_k <= z },  inf{ y_k + (d_hi - d_lo) : z <= z_k } ],

the tightest set-valued map containing every map f~ + [d_lo, d_hi] (f~ monotone)
that is consistent with the data. Empty sup/inf give -inf/+inf.
"""

from __future__ import annotations

import numpy as np

from ._signs import normalize_signs

__all__ = ["MinimalSimulatingMap"]


def _as_data(Z, Y):
    Z = np.atleast_2d(np.asarray(Z, dtype=float))
    Y = np.asarray(Y, dtype=float)
    if Y.ndim == 1:
        Y = Y[:, None]
    if Z.shape[0] != Y.shape[0]:
        raise ValueError(f"Z has {Z.shape[0]} rows but Y has {Y.shape[0]}")
    if not (np.all(np.isfinite(Z)) and np.all(np.isfinite(Y))):
        raise ValueError("data must be finite")
    return Z, Y


def _as_bounds(d_lo, d_hi, m):
    d_lo = np.broadcast_to(np.asarray(d_lo, dtype=float), (m,)).copy()
    d_hi = np.broadcast_to(np.asarray(d_hi, dtype=float), (m,)).copy()
    if np.any(d_lo > d_hi):
        raise ValueError("disturbance bounds must satisfy d_lo <= d_hi")
    return d_lo, d_hi


class MinimalSimulatingMap:
    """Exact (pointwise) minimal simulating map of a data set.

    Parameters
    ----------
    Z : (K, n) array of inputs z_k.
    Y : (K, m) array of outputs y_k (or (K,) for m = 1).
    d_lo, d_hi : disturbance bounds, scalars or (m,) arrays.
    signs : optional (m, n) or (n,) monotonicity pattern (see ``ddma._signs``).

    Evaluation costs O(|K| n) per query point. For large data sets use
    :class:`ddma.PartitionedSimulatingMap`, which is computed once on a grid.
    """

    def __init__(self, Z, Y, d_lo=0.0, d_hi=0.0, signs=None):
        self.Z, self.Y = _as_data(Z, Y)
        self.d_lo, self.d_hi = _as_bounds(d_lo, d_hi, self.Y.shape[1])
        self.signs = normalize_signs(signs, self.m, self.n)

    @property
    def n(self) -> int:
        """Input dimension."""
        return self.Z.shape[1]

    @property
    def m(self) -> int:
        """Output dimension."""
        return self.Y.shape[1]

    @property
    def theta(self) -> np.ndarray:
        """Width of the disturbance interval, d_hi - d_lo."""
        return self.d_hi - self.d_lo

    def bounds(self, z, chunk: int = 2_000_000) -> tuple[np.ndarray, np.ndarray]:
        """Lower and upper bounds of S_m at the query points ``z`` (M, n)."""
        z = np.atleast_2d(np.asarray(z, dtype=float))
        if z.shape[1] != self.n:
            raise ValueError(f"query has dimension {z.shape[1]}, data has {self.n}")
        M, K = z.shape[0], self.Z.shape[0]
        lower = np.full((M, self.m), -np.inf)
        upper = np.full((M, self.m), np.inf)
        if K == 0:
            return lower, upper
        step = max(1, chunk // max(1, K * self.n))
        y_up = self.Y + self.theta
        y_lo = self.Y - self.theta
        for s in range(0, M, step):
            diff = self.Z[None, :, :] - z[s : s + step, None, :]  # (B, K, n): z_k - z
            for i in range(self.m):
                sd = diff * self.signs[i]
                above = np.all(sd >= 0, axis=2)  # z <= z_k in the order of output i
                below = np.all(sd <= 0, axis=2)  # z_k <= z
                upper[s : s + step, i] = np.where(above, y_up[None, :, i], np.inf).min(axis=1)
                lower[s : s + step, i] = np.where(below, y_lo[None, :, i], -np.inf).max(axis=1)
        return lower, upper

    __call__ = bounds

    def f_bounds(self, z) -> tuple[np.ndarray, np.ndarray]:
        """Bounds on the unknown monotone function f itself.

        f(z) lies in [S_lo(z) - d_lo, S_hi(z) - d_hi]
        = [sup{y_k - d_hi : z_k <= z}, inf{y_k - d_lo : z <= z_k}].
        """
        lo, hi = self.bounds(z)
        return lo - self.d_lo, hi - self.d_hi

    def estimate(self, z) -> np.ndarray:
        """Midpoint of the f-bounds (set-membership estimate); nan where unbounded."""
        lo, hi = self.f_bounds(z)
        with np.errstate(invalid="ignore"):
            mid = 0.5 * (lo + hi)
        mid[~np.isfinite(mid)] = np.nan
        return mid

    def merge(self, other: MinimalSimulatingMap) -> MinimalSimulatingMap:
        """Map of the union of both data sets; equals the intersection of both maps."""
        if not (
            np.array_equal(self.d_lo, other.d_lo)
            and np.array_equal(self.d_hi, other.d_hi)
            and np.array_equal(self.signs, other.signs)
        ):
            raise ValueError("maps must share disturbance bounds and sign pattern")
        return MinimalSimulatingMap(
            np.vstack([self.Z, other.Z]), np.vstack([self.Y, other.Y]),
            self.d_lo, self.d_hi, self.signs,
        )

    def is_consistent(self, tol: float = 1e-12) -> bool:
        """Whether some monotone f + [d_lo, d_hi] can explain the data.

        Equivalent to y_k in S_m(z_k) for every data point, i.e. y_k <= y_l + (d_hi - d_lo)
        whenever z_k <= z_l. A violation shows that the monotonicity assumption (or the
        sign pattern) or the disturbance bounds are wrong.
        """
        lo, hi = self.bounds(self.Z)
        return bool(np.all((lo <= self.Y + tol) & (self.Y <= hi + tol)))
